    require(doc.save_bytes()==before&&selected==999&&doc.redo()&&doc.save_bytes()==changed,"Mute rejected input preserves bytes selection and redo");
    require(!doc.edit_mute(0,doc.mutes()[0])&&doc.save_bytes()==changed,"Mute no-op unchanged");SegmentDocument restored;restored.load(changed);require(restored.save_bytes()==changed&&!restored.dirty()&&restored.mutes().size()==5,"Mute save reload");
