    auto root=Chunk::parse(doc.save_bytes());auto peer=mute_track();add_mute_event(peer,{0,33,33});root.find("LIST","trkl")->children.push_back(peer);restored.load(root.encode());require(restored.edit_mute(0,{1,33,0},1)&&restored.mutes(0).size()==5&&restored.mutes(1)[0].time==1,"Mute nth-track ownership");
    const auto base=dir/L"mute-document";std::filesystem::create_directories(base);restored.save((base/L"Created.sgp").wstring());Framework host;host.open_segment((base/L"Created.sgp").wstring());host.save_project((base/L"mute-document.pro").wstring());Framework reload;reload.open_project((base/L"mute-document.pro").wstring());require(reload.document(0).save_bytes()==restored.save_bytes()&&!reload.dirty(),"Mute native Project separate Framework reload");
    auto extended=mute_track();add_mute_event(extended,{768,0,mute_channel_silent});auto& data=extended.find("mute")->data;put32(data,0,15);data.insert(data.end(),{0xaa,0xbb,0xcc});extended.find("mute")->padding=0x7f;Chunk opaque;opaque.id="zzzz";opaque.data={1,2,3};opaque.padding=0x7e;extended.children.push_back(opaque);const auto saved=extended.encode();require(change_mute_event(extended,0,{769,0,0}),"Mute extended stride edit");auto expected=Chunk::parse(saved);put32(expected.find("mute")->data,4,769);put32(expected.find("mute")->data,12,0);require(extended.encode()==expected.encode(),"Mute extensions siblings padding retained");auto target=Chunk::parse(saved);require(paste_mute_event(target,copy_mute_event(extended,0),2304)&&target.find("mute")->data.size()==34&&target.find("mute")->data[31]==0xaa,"Mute clipboard extension retained");auto shortTarget=mute_track();const auto shortBefore=shortTarget.encode();rejected([&]{paste_mute_event(shortTarget,copy_mute_event(extended,0),0);},"Mute incompatible stride refuses truncation");require(shortTarget.encode()==shortBefore,"Mute stride rejection atomic");
    for(auto mutation:{0,1,2,3}){auto bad=Chunk::parse(saved);auto p=bad.find("mute");if(mutation==0)put32(p->data,0,11);if(mutation==1)p->data.pop_back();if(mutation==2)put32(p->data,8,0xffffffffu);if(mutation==3)bad.children.push_back(*p);const auto b=bad.encode();rejected([&]{change_mute_event(bad,0,{1,2,0});},"Mute malformed source rejects");require(bad.encode()==b,"Mute malformed source atomic");}
    if(!original.empty())for(const auto name:{L"OriginalEmptyMute.sgp",L"OriginalOneBeatMute.sgp",L"OriginalMuteRemap.sgp"}){auto bytes=read_file((std::filesystem::path(original)/name).wstring());SegmentDocument observed;observed.load(bytes);auto events=observed.mutes();bool none=std::wstring(name)==L"OriginalEmptyMute.sgp",remap=std::wstring(name)==L"OriginalMuteRemap.sgp";require(observed.save_bytes()==bytes&&events.size()==(none?0:remap?4:2),"Original Mute no-edit bytes and count");if(!none)require(events[0].time==768&&events[0].channel==0&&events[0].map==mute_channel_silent&&events[1].time==1536&&events[1].map==0,"Original one-beat Mute/restore GUI contract");if(remap)require(events[2].time==0&&events[2].channel==1&&events[2].map==0&&events[3].time==observed.length()&&events[3].map==1,"Original Remap terminal restore GUI contract");require(observed.add_mute({2304,17,mute_channel_silent}),"Original Mute owned DWORD edit");auto edited=observed.save_bytes();require(observed.undo()&&observed.save_bytes()==bytes&&observed.redo()&&observed.save_bytes()==edited,"Original Mute exact history");observed.save((base/name).wstring());SegmentDocument reopened;reopened.load(read_file((base/name).wstring()));require(reopened.save_bytes()==edited&&reopened.mutes().size()==events.size()+1,"Original Mute edited save reload");}
    {
        SegmentDocument beat;const auto initial=beat.save_bytes();
        require(beat.toggle_mute_beat(0,1000),"Beat cell aligns interior click to quarter-note boundaries");const auto one=beat.save_bytes();auto events=beat.mutes();
        require(events.size()==2&&events[0].time==768&&events[0].channel==0&&events[0].map==mute_channel_silent&&events[1].time==1536&&events[1].map==0,"One beat matches original 768-silent/1536-restore pair");
        require(beat.undo()&&beat.save_bytes()==initial&&!beat.dirty()&&!beat.can_undo()&&beat.can_redo(),"One beat is one full-document history entry including absent track");
        const auto rejectCell=[&](std::uint32_t channel,std::int32_t at){const auto bytes=beat.save_bytes();const bool dirty=beat.dirty(),undo=beat.can_undo(),redo=beat.can_redo();return !beat.toggle_mute_beat(channel,at)&&beat.save_bytes()==bytes&&beat.dirty()==dirty&&beat.can_undo()==undo&&beat.can_redo()==redo;};
        for(auto channel:{0xfffffffcu,0xfffffffdu,0xfffffffeu,0xffffffffu})require(rejectCell(channel,768),"Reserved beat-cell PChannel rejects atomically with redo retained");
        require(rejectCell(0,-1)&&rejectCell(0,beat.length()),"Beat-cell clock bounds reject without creating absent track");
        rejected([&]{beat.toggle_mute_beat(0,768,999);},"Absent nth Mute track refuses beat cell");require(beat.save_bytes()==initial&&beat.can_redo()&&!beat.dirty(),"Invalid nth cell leaves full document checkpoint and redo");
        require(beat.redo()&&beat.save_bytes()==one,"Rejected cell leaves earlier edit available for Redo");
        require(beat.toggle_mute_beat(0,768)&&beat.mutes().empty(),"Click muted beat restores channel and removes redundant pair");const auto unmuted=beat.save_bytes();
        require(beat.undo()&&beat.save_bytes()==one&&beat.redo()&&beat.save_bytes()==unmuted,"Cell unmute is a single atomic UndoRedo step");
        beat.load(one);require(beat.toggle_mute_beat(0,1536),"Adjacent beat can extend mute");events=beat.mutes();
        require(events.size()==2&&events[0].time==768&&events[1].time==2304&&events[1].map==0,"Adjacent mute merges shared restore boundary");
        require(beat.toggle_mute_beat(0,768),"First beat of merged interval can unmute");events=beat.mutes();
        require(events.size()==2&&events[0].time==1536&&events[0].map==mute_channel_silent&&events[1].time==2304,"Unmuting first beat preserves later muted beat");
        SegmentDocument split;require(split.add_mute({0,0,mute_channel_silent})&&split.add_mute({2304,0,0})&&split.toggle_mute_beat(0,768),"Interior unmute splits sustained mute interval");events=split.mutes();
        require(events.size()==4&&events[0].time==0&&events[1].time==768&&events[1].map==0&&events[2].time==1536&&events[2].map==mute_channel_silent&&events[3].time==2304,"Split interval restores exact states before and after selected beat");
        for(auto channel:{16u,32u,0xfffffffbu}){SegmentDocument high;require(high.toggle_mute_beat(channel,768)&&high.mutes().size()==2&&high.mutes()[0].channel==channel&&high.mutes()[1].map==channel,"Beat cells retain full ordinary DWORD PChannel and restore identity");}
        SegmentDocument signature;require(signature.set_meter(0,6,8,4)&&signature.toggle_mute_beat(16,500),"Beat cell follows selected 6/8 denominator");events=signature.mutes();
        require(events.size()==2&&events[0].time==384&&events[1].time==768,"Eighth-note cell uses 384 clocks rather than fixed 768");
        auto partial=Chunk::parse(initial);put32(partial.find("segh")->data,4,1000);SegmentDocument terminal;terminal.load(partial.encode());require(terminal.toggle_mute_beat(0,999),"Partial final beat can be muted");events=terminal.mutes();
        require(events.size()==2&&events[0].time==768&&events[1].time==1000,"Final beat restore is clipped to Segment length");
        SegmentDocument mixed;require(mixed.add_mute({900,0,mute_channel_silent}),"Mixed beat fixture");const auto mixedBytes=mixed.save_bytes();const auto mixedDirty=mixed.dirty(),mixedUndo=mixed.can_undo();
        require(!mixed.toggle_mute_beat(0,768)&&mixed.save_bytes()==mixedBytes&&mixed.dirty()==mixedDirty&&mixed.can_undo()==mixedUndo,"Interior event refuses cell edit without losing source data");
        SegmentDocument remapped;require(remapped.add_mute({0,16,32})&&remapped.toggle_mute_beat(16,768),"Temporary mute can preserve surrounding remapping");events=remapped.mutes();
        require(events.size()==3&&events[0].map==32&&events[1].time==768&&events[1].map==mute_channel_silent&&events[2].time==1536&&events[2].map==32,"One-beat mute restores prior remap at end without changing earlier event");
        auto grouped=Chunk::parse(one);auto& tracks=grouped.find("LIST","trkl")->children;auto peer=mute_track();put32(peer.find("trkh")->data,20,2);add_mute_event(peer,{0,32,32});tracks.push_back(peer);tracks.push_back(mute_track());const auto groupedBytes=grouped.encode();
        SegmentDocument group;group.load(groupedBytes);group.select_track_group(2);require(group.toggle_mute_beat(32,768),"Cell follows selected group");
        auto groupTree=Chunk::parse(group.save_bytes());require(groupTree.find("LIST","trkl")->children[tracks.size()-3].encode()==tracks[tracks.size()-3].encode()&&groupTree.find("LIST","trkl")->children.back().encode()==tracks.back().encode(),"Cell edit preserves same-type peer tracks outside selected group");
        group.load(groupedBytes);require(group.toggle_mute_beat(17,768,1)&&group.mutes(0).size()==2&&group.mutes(1).size()==2&&group.mutes(1)[0].channel==17,"Cell follows nth Mute track without touching first track");
        auto opaqueTrack=mute_track();add_mute_event(opaqueTrack,{0,0,16});add_mute_event(opaqueTrack,{2304,0,0});add_mute_event(opaqueTrack,{0,32,16});
        auto& bytes=opaqueTrack.find("mute")->data;Bytes enlarged(4);put32(enlarged,0,15);for(size_t offset=4;offset<bytes.size();offset+=12){enlarged.insert(enlarged.end(),bytes.begin()+offset,bytes.begin()+offset+12);enlarged.insert(enlarged.end(),{0xaa,0xbb,0xcc});}bytes=enlarged;opaqueTrack.find("mute")->padding=0x7f;opaqueTrack.children.push_back(opaque);const auto opaqueBefore=opaqueTrack;
        require(set_mute_interval(opaqueTrack,0,768,1536,true),"Interval authoring accepts extended native stride");
        const auto& output=opaqueTrack.find("mute")->data;require(read32(output,0)==15&&Bytes(output.begin()+4,output.begin()+19)==Bytes(enlarged.begin()+4,enlarged.begin()+19)&&Bytes(output.end()-15,output.end())==Bytes(enlarged.end()-15,enlarged.end()),"Untouched source and peer-channel records retain exact extension bytes");
        require(opaqueTrack.children.back().encode()==opaqueBefore.children.back().encode()&&opaqueTrack.find("mute")->padding==0x7f,"Interval edit retains opaque sibling and payload padding");const auto authored=opaqueTrack.encode();
        require(!set_mute_interval(opaqueTrack,0,768,1536,true)&&opaqueTrack.encode()==authored,"Identical interval adds no mutation");
        auto noMute=mute_track();const auto noMuteBytes=noMute.encode();require(!set_mute_interval(noMute,0,768,1536,false)&&noMute.encode()==noMuteBytes,"Unmute of absent payload is byte-identical no-op");
        auto unsorted=opaqueBefore;auto& shuffled=unsorted.find("mute")->data;std::swap_ranges(shuffled.begin()+4,shuffled.begin()+19,shuffled.begin()+19);const auto unsortedBytes=unsorted.encode();require(!set_mute_interval(unsorted,0,768,1536,true)&&unsorted.encode()==unsortedBytes,"Unordered source is refused instead of silently reordering unrelated data");
        auto duplicate=opaqueBefore;auto& duplicated=duplicate.find("mute")->data;Bytes first(duplicated.begin()+4,duplicated.begin()+19);duplicated.insert(duplicated.begin()+4,first.begin(),first.end());const auto duplicateBytes=duplicate.encode();require(!set_mute_interval(duplicate,0,768,1536,true)&&duplicate.encode()==duplicateBytes,"Duplicate source key refuses atomically");
        beat.load(one);beat.save((base/L"BeatEdited.sgp").wstring());SegmentDocument reopened;reopened.load(read_file((base/L"BeatEdited.sgp").wstring()));require(reopened.save_bytes()==one&&reopened.mutes().size()==2&&!reopened.dirty()&&!reopened.can_undo(),"Beat native save reload retains exact pair with fresh history");
        if(!original.empty()){
            const auto source=read_file((std::filesystem::path(original)/L"OriginalEmptyMute.sgp").wstring());SegmentDocument observed;observed.load(source);require(observed.toggle_mute_beat(0,768),"Original empty Mute fixture accepts same beat click");
            const auto expectedRoot=Chunk::parse(read_file((std::filesystem::path(original)/L"OriginalOneBeatMute.sgp").wstring()));const Chunk* originalPayload=nullptr;for(const auto& track:expectedRoot.find("LIST","trkl")->children)if(track.find("mute"))originalPayload=track.find("mute");
            const auto actualRoot=Chunk::parse(observed.save_bytes());const Chunk* actualPayload=nullptr;for(const auto& track:actualRoot.find("LIST","trkl")->children)if(track.find("mute"))actualPayload=track.find("mute");
            require(originalPayload&&actualPayload&&originalPayload->encode()==actualPayload->encode(),"Authored one-beat native payload exactly equals independently saved original payload");
            require(observed.undo()&&observed.save_bytes()==source&&!observed.dirty(),"Original beat edit Undo restores exact original file");
        }
    }
    require(doc.save_bytes()!=empty,"Mute materialized owned track");
